/* nodes details for region "waves", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("waves.nodes",{"nodes":{
"float-sink":{"description":{"zh":"浮力等于排开的水的重量：橡皮泥捏成船，排开的水变多了，浮力就大到托得住它；钢船能浮也是同理——算上船舱里的空气，整船的平均密度小于水。理想不可压缩水，忽略表面张力与翻覆稳定性。","en":"Buoyant force equals the weight of the displaced water: shape plasticine into a boat and it displaces more water, so buoyancy grows enough to hold it up. A steel ship floats the same way — counting the air in its hull, the ship's average density is below water's. Ideal incompressible water; surface tension and tipping stability ignored."},"formula":"B = ρ_water · V_sub","source":"../physics/matter/float-sink/#step1","lessons":[{"slug":"float-sink","step":1,"category":"physics","stage":"primary","primary":true}],"note":"physics (forces & fluids); no atlas group exists for it"},
"pinhole-ratio":{"description":{"zh":"在均匀介质的孔心光线模型中，物距u与屏距v均为正，带符号像高差与物高之比为−v/u；负号表示倒像，正尺寸取其绝对值。","en":"In the homogeneous-medium central-ray model, object distance u and screen distance v are positive. Signed image-height difference divided by object height is−v/u: the negative sign marks inversion; positive size uses the absolute value."},"formula":"h_s/H = −v/u; h = |h_s|","source":"../physics/optics/pinhole-camera/#geometry-bridge","help":{"title":{"zh":"符号、单位与光学边界","en":"Symbols, units and optical scope"},"body":{"zh":"H与h是正的长度(cm)，h_s是按对应端点相减的带符号坐标差(cm)，M=h_s/H无量纲。物体和屏平行，孔心取原点且Y向上；相似三角形来自直线关系。这里没有透镜焦距条件；有限孔径几何模糊和极小孔衍射需分别说明。","en":"H and h are positive lengths(cm); h_s is the signed difference between corresponding image endpoints(cm), and M=h_s/H is dimensionless. Object and screen planes are parallel, the hole is the origin, and Y points upward. Similar triangles follow the straight-line geometry. No lens focal-length condition is used; finite-aperture geometric blur and tiny-aperture diffraction have distinct scopes."},"sources":[{"href":"https://openstax.org/books/elementary-algebra-2e/pages/8-7-solve-proportion-and-similar-figure-applications","label":{"zh":"相似与比例 · OpenStax ↗","en":"Similarity & proportion · OpenStax ↗"}},{"href":"https://openstax.org/books/college-physics-2e/pages/25-1-the-ray-aspect-of-light","label":{"zh":"射线近似 · OpenStax ↗","en":"Ray approximation · OpenStax ↗"}},{"href":"https://openstax.org/books/college-physics-2e/pages/27-6-limits-of-resolution-the-rayleigh-criterion","label":{"zh":"衍射与分辨率 · OpenStax ↗","en":"Diffraction & resolution · OpenStax ↗"}}]},"lessons":[{"slug":"pinhole-camera","step":null,"category":"physics","stage":"primary","primary":true}],"aliases":{"zh":["相机","相机拍照","相机是怎么成像的"],"en":["camera","how does a camera work"]}},
"sound-vibration":{"description":{"zh":"声音由物体振动产生：振幅决定强度，频率决定音高，需要介质传播，速度随介质不同。鼓面运动为示意的衰减简谐运动。","en":"Sound comes from an object's vibration: amplitude sets intensity, frequency sets pitch, a medium is needed, and speed depends on the medium. The drumhead motion is an illustrative decaying oscillation."},"formula":"I ∝ A², d = v·t/2","source":"../physics/waves/sound-vibration/#step2","lessons":[{"slug":"sound-vibration","step":2,"category":"physics","stage":"primary","primary":true}]},
"buoyancy-archimedes":{"description":{"zh":"浸在液体里的物体受到向上的浮力 F = ρ液·g·V排，大小等于排开液体的重力，全浸入后与深度无关。适用于静止、不可压缩的液体与刚性物体。","en":"An object in a liquid feels an upward force F = ρ_liq·g·V_displaced equal to the weight of the liquid it displaces, independent of depth once fully submerged. Valid for still, incompressible liquids and rigid objects."},"formula":"F_b = ρ_liq · g · V_displaced","source":"../physics/matter/buoyancy-archimedes/#step1","lessons":[{"slug":"buoyancy-archimedes","step":1,"category":"physics","stage":"junior","primary":true}],"note":"No mechanics group in the atlas; group left OTHER for the coordinator.","aliases":{"zh":["船为什么不会沉","船为什么能浮起来"],"en":["why do ships float","why do boats float"]}},
"convex-lens":{"description":{"zh":"物体离凸透镜远近不同，像的大小、正倒、虚实都会变：物距大于二倍焦距成缩小倒立的实像，在一倍与二倍焦距之间成放大倒立的实像，小于一倍焦距成放大正立的虚像——三条特殊光线就能画出像在哪里。","en":"How far an object sits from a convex lens changes the image’s size, orientation and kind: beyond twice the focal length it is a smaller inverted real image, between one and two focal lengths a larger inverted real image, and inside one focal length a larger upright virtual image — three special rays locate it."},"formula":"1/f = 1/u + 1/v","source":"../physics/optics/lens/#step2","lessons":[{"slug":"lens","step":2,"category":"physics","stage":"junior","primary":true}],"aliases":{"zh":["凸透镜成像规律","焦距","实像和虚像的区别","放大镜原理","一倍焦距分虚实，二倍焦距分大小","薄透镜公式","透镜成像","三条特殊光线"],"en":["convex lens image rules","focal length","real image vs virtual image","how a magnifying glass works","f splits real from virtual, 2f splits larger from smaller","thin lens equation","lens imaging","three principal rays"]}},
"eye-vision":{"description":{"zh":"把眼睛简化成薄透镜加视网膜：调节改变屈光力使像回到视网膜；眼轴偏长焦点落在网膜前是近视，凹透镜（P < 0）矫正，远视相反；瞳孔越小景深越大。简约眼模型，非验光建议。","en":"A reduced eye is a thin lens plus a retina: accommodation changes the lens power to bring the image back onto the retina; an axis that is too long puts the focus in front of the retina (myopia), corrected by a concave lens (P < 0), and hyperopia is the opposite; a smaller pupil gives a larger depth of field. A reduced-eye model, not an eye test."},"formula":"1/v = 1/f − 1/u","source":"../physics/optics/eye-vision/#step2","lessons":[{"slug":"eye-vision","step":2,"category":"physics","stage":"junior","primary":true}],"note":"Edges: snell and pinhole-ratio are existing atlas nodes; eye-vision is a new concept id.","aliases":{"zh":["眼睛是怎么看东西的","眼睛看东西","近视","远视"],"en":["myopia","nearsighted","short-sighted","farsighted","how do eyes see"]}},
"lever-pulley":{"description":{"zh":"杠杆平衡看力矩：两边的力 × 力臂相等，所以把支点挪近重物就能用小力撬起大物；但省力必费距离——手做的功等于重物得到的功，滑轮组省几倍力就要多拉几倍绳。","en":"A lever balances when the torques match — force × lever arm on each side — so moving the fulcrum toward the load lets a small force lift a big one; but saved force always costs distance: the work you put in equals the work done on the load, and a pulley system that divides the force by n makes you pull n times as much rope."},"formula":"F₁·l₁ = F₂·l₂","source":"../physics/mechanics/lever-pulley/#step1","lessons":[{"slug":"lever-pulley","step":1,"category":"physics","stage":"junior","primary":true}],"aliases":{"zh":["杠杆原理","力矩","力臂","滑轮组","省力杠杆","动滑轮 定滑轮","为什么撬棍能撬起大石头","机械效益"],"en":["lever principle","torque / moment","lever arm","block and tackle / pulley system","force-saving lever","movable and fixed pulleys","how can a crowbar lift a heavy rock","mechanical advantage"]}},
"momentum-collision":{"description":{"zh":"动量是质量乘速度的账本：同样的速度，质量不同，动量就不同。碰撞时动量总守恒，冲量（力乘时间）是动量改变多少；弹性碰撞还守恒动能，粘性碰撞只守恒动量。","en":"Momentum is the mass-times-velocity ledger: same speed, different mass, different momentum. Total momentum is always conserved in a collision; impulse (force times time) is how much it changes. Elastic collisions also conserve kinetic energy; sticky ones conserve momentum only."},"formula":"p = mv, J = F·Δt","source":"../physics/mechanics/momentum-collision/#step2","lessons":[{"slug":"momentum-collision","step":2,"category":"physics","stage":"junior","primary":true}],"aliases":{"zh":["动量守恒","动量守恒定律"],"en":["conservation of momentum","momentum conservation"]}},
"pressure":{"description":{"zh":"压强 p = F/S：同样的力，接触面积越小压强越大；液体内 p = ρgh；密闭液体中压强处处相等。适用于静止、不可压缩液体与理想接触面的教学模型。","en":"Pressure p = F/S: the same force on a smaller area gives higher pressure; in a liquid p = ρgh; in a sealed liquid pressure is the same everywhere. A teaching model for still, incompressible liquids and ideal contact areas."},"formula":"p = F / S","source":"../physics/matter/pressure/#step0","lessons":[{"slug":"pressure","step":0,"category":"physics","stage":"junior","primary":true}],"note":"No physics-mechanics group exists in the atlas; 'work' style nodes live under waves, so group is left OTHER for the coordinator."},
"snell":{"description":{"zh":"两角都从界面法线量起，n=c/v为无量纲折射率。斜光从高n到低n时可能没有实折射角；临界点与严格超临界分开。筷子插水里看起来折断、光纤把光关在芯里，都是它：入射角越大、折射角偏得越多，超过临界角就全反射。","en":"Both angles start at the interface normal; n=c/v is dimensionless. Oblique rays from higher to lower index may have no real refraction angle. The critical limiting case is distinct from strictly supercritical incidence. A chopstick looking broken in water, and a fibre keeping light inside its core, are both this: the larger the incidence angle, the more the refracted angle bends, and past the critical angle comes total reflection."},"formula":"n₁ sinθ₁ = n₂ sinθ₂","source":"../physics/optics/reflection-refraction/#snell-bridge","help":{"title":{"zh":"法线、正弦范围与临界条件","en":"Normal, sine range and critical conditions"},"body":{"zh":"法线垂直界面。固定均匀、无吸收介质，s=(n₁/n₂)sinθ₁；s>1没有实θ₂。仅n₁>n₂有θc=arcsin(n₂/n₁)：θ₁=θc对应沿界面极限光线，θ₁>θc为全反射。本页只算方向，不算能量比例或传播时间。","en":"The normal is perpendicular to the interface. For fixed homogeneous, non-absorbing media, s=(n₁/n₂)sinθ₁; s>1 gives no real θ₂. Only n₁>n₂ has θc=arcsin(n₂/n₁): equality gives the limiting ray along the interface; θ₁>θc gives total internal reflection. The lesson models direction, not energy fractions or travel time."},"sources":[{"href":"https://openstax.org/books/university-physics-volume-3/pages/1-3-refraction","label":{"zh":"折射与Snell关系 · OpenStax ↗","en":"Refraction & Snell · OpenStax ↗"}},{"href":"https://openstax.org/books/university-physics-volume-3/pages/1-4-total-internal-reflection","label":{"zh":"临界角与全反射 · OpenStax ↗","en":"Critical angle & TIR · OpenStax ↗"}}]},"lessons":[{"slug":"reflection-refraction","step":null,"category":"physics","stage":"junior","primary":true}]},
"sound-waves":{"description":{"zh":"声音是介质里疏密的传播：波长 λ = v/f，v = fλ 连起周期与波长；两个相近频率叠加产生拍；谐波的强弱决定音色；用声速估算雷电距离；可听声、次声与超声的频率范围。一维线性无损耗模型，本页不播放声音，只画波形。","en":"Sound is a squeeze-and-loosen pattern travelling in a medium: wavelength λ = v/f and v = fλ link period and wavelength; two close frequencies add into beats; harmonic strengths set timbre; the speed of sound estimates thunder distance; and the frequency bands of audible, infra- and ultrasound. A one-dimensional linear lossless model; this page plays no sound and only draws waveforms."},"formula":"v = f·λ,  beat = |f₁ − f₂|","source":"../physics/waves/sound-waves/#step1","lessons":[{"slug":"sound-waves","step":1,"category":"physics","stage":"junior","primary":true}],"aliases":{"zh":["声音传播","声音是怎么传播的"],"en":["how does sound travel"]}},
"velocity-vt":{"description":{"zh":"速度–时间图：曲线上每点的纵坐标就是那一刻的速度，斜率是加速度，曲线下面积是位移。斜率为正速度在变大、为零速度不变；面积带符号，往回走的那段要减掉。","en":"A velocity–time graph: each point's height is the velocity at that instant, the slope is acceleration, and the area under the curve is displacement. Positive slope means speeding up, zero slope means steady speed; area carries a sign, so the way-back stretch subtracts."},"formula":"slope = a, area = Δx","source":"../physics/mechanics/velocity-vt/#step1","lessons":[{"slug":"velocity-vt","step":1,"category":"physics","stage":"junior","primary":true}]},
"doppler-effect":{"description":{"zh":"运动声源的波前被挤密或拉疏，给出前后方听者的频率、掠过曲线与马赫锥；源动、听者静止、静止介质的几何模型。","en":"A moving source's wavefronts bunch up or stretch out, giving heard frequency ahead and behind, a pass-by curve and the Mach cone; a geometric model with moving source, still listener and still medium."},"formula":"f′ = f/(1 − (v/c) cosθ)","source":"../physics/waves/doppler-effect/#step2","lessons":[{"slug":"doppler-effect","step":2,"category":"physics","stage":"senior","primary":true}]},
"interference":{"description":{"zh":"线性波在同一点的位移相加；同频等振幅时，到达相位差决定合振幅。相干表示相对相位保持固定。双缝条纹、降噪耳机都是它：同相叠加变响变亮、反相抵消变静变暗——相位差就是明暗的开关。","en":"Linear-wave displacements add at the same point. For equal-amplitude, equal-frequency waves, arrival phase determines the resultant amplitude; coherence means a fixed relative phase. Double-slit fringes and noise-cancelling headphones are both this: in-phase addition grows louder and brighter, opposite-phase cancellation grows quieter and darker — phase difference is the brightness switch."},"formula":"B = 2A |cos(δ/2)|","source":"../physics/waves/interference/#step1","help":{"title":{"zh":"到达相位与模型条件","en":"Arrival phase and model conditions"},"body":{"zh":"源2初相位为φ时，带符号路程差d=r₂−r₁给出δ=φ−2πd/λ。此公式假设P处两列波同频等振幅；振幅不是强度，本课不计算二维能流。","en":"With source 2 phaseφ and directed d=r₂−r₁, δ=φ−2πd/λ. Equal frequency and equal received amplitude at P are assumed. Amplitude is not intensity; this lesson does not calculate 2D energy flux."},"sources":[{"href":"https://openstax.org/books/university-physics-volume-1/pages/16-5-interference-of-waves","label":{"zh":"OpenStax16.5 · 叠加与相位 ↗","en":"OpenStax16.5 · superposition & phase ↗"}}]},"lessons":[{"slug":"interference","step":1,"category":"physics","stage":"senior","primary":true}]},
"net-force":{"description":{"zh":"在惯性参考系、质量恒定时，合外力等于质量乘加速度。它决定速度如何改变，而不是此刻速度有多大。","en":"In an inertial frame with constant mass, the sum of external forces equals mass times acceleration. It determines how velocity changes, not the current velocity."},"formula":"ΣF = m a","source":"https://openstax.org/books/university-physics-volume-1/pages/5-3-newtons-second-law"},
"newton-laws":{"description":{"zh":"在无摩擦、有摩擦和斜面上推箱子，用频闪残影看加速度如何由合力与质量决定；再用相互推开的小车和电梯里的秤检验第三定律与 N=m(g+a)。质点、恒定质量、g=9.8 的简化模型。","en":"Push a box on ice, a rough floor and a ramp and see in stroboscopic ghosts how acceleration comes from net force and mass; then test the third law with two carts and N = m(g+a) with a lift scale. A point-mass, constant-mass, g = 9.8 model."},"formula":"a = F_net / m","source":"../physics/mechanics/newton-laws/#step2","lessons":[{"slug":"newton-laws","step":2,"category":"physics","stage":"senior","primary":true}],"note":"Mechanics pages live in atlas group \"waves\" next to net-force and work-energy; fragment uses that group.","aliases":{"zh":["牛顿定律","牛顿三大定律","牛顿第一定律","牛顿第三定律","惯性定律","作用力与反作用力"],"en":["newton's laws","newtons laws","laws of motion","newton's first law","newton's third law","action and reaction"]}},
"oscillation":{"description":{"zh":"理想弹簧振子的回复力与位移成正比、方向相反。在无阻尼、无持续外力驱动时，位移随时间呈正弦变化；回复力仍然存在。","en":"An ideal spring has a restoring force proportional and opposite to displacement. Without damping or driving, its motion is sinusoidal."},"formula":"m x″ + kx = 0","source":"https://openstax.org/books/university-physics-volume-1/pages/15-1-simple-harmonic-motion","help":{"title":{"zh":"x′ 和 x″ 分别读什么？","en":"What do x′ and x″ mean?"},"body":{"zh":"x 是相对平衡位置的坐标（m）。x′=dx/dt 是带方向的速度（m/s）；再对时间求一次导数，x″=d²x/dt² 就是加速度（m/s²）。两个撇号表示求两次导数，不是把 x 平方。","en":"x is position relative to equilibrium (m). x′=dx/dt is signed velocity (m/s); differentiating once more gives x″=d²x/dt², acceleration (m/s²). Two primes mean two time derivatives, not x squared."},"sources":[{"href":"https://openstax.org/books/university-physics-volume-1/pages/3-3-average-and-instantaneous-acceleration","label":{"zh":"OpenStax · 加速度与变化率 ↗","en":"OpenStax · acceleration as a rate ↗"}}]},"aliases":{"zh":["单摆","单摆周期","简谐运动","弹簧振子"],"en":["pendulum","pendulum period","simple harmonic motion","spring oscillator"]}},
"projectile-circular":{"description":{"zh":"把速度分成水平与竖直两份看抛体，用向心加速度理解匀速圆周，再用点质量引力积分演示牛顿大炮：水平速度达到约 7.9 km/s 就绕地球转，11.2 km/s 脱离。忽略空气阻力与地球自转。","en":"Split velocity into horizontal and vertical parts for projectiles, use centripetal acceleration to understand uniform circular motion, then integrate point-mass gravity for Newton’s cannon: about 7.9 km/s circles the Earth and 11.2 km/s escapes. Air drag and Earth rotation are ignored."},"formula":"R = v² sin2θ / g,  a = v² / r","source":"../physics/mechanics/projectile-circular/#step4","lessons":[{"slug":"projectile-circular","step":4,"category":"physics","stage":"senior","primary":true}],"note":"Mechanics group follows atlas net-force / work-energy (group \"waves\").","aliases":{"zh":["抛体运动","抛物线轨迹","平抛运动","斜抛运动"],"en":["projectile motion"]}},
"seismic-waves":{"description":{"zh":"P 波快、S 波慢，用 S−P 时间估震中距并用三个台站画圆定位；用球对称速度分层追踪射线，看波线向上弯曲、P 波影区与 S 波被液态外核挡住；再看震级与能量的对数关系。教学用的粗略一维模型，影区角度与真实地球不同。","en":"P is fast and S slow: estimate the epicentre distance from S−P and locate it with three stations’ circles; trace rays through a spherically symmetric layered speed model to see rays curve upward, the P shadow zone and S waves blocked by the liquid outer core; then the logarithmic magnitude–energy relation. A coarse one-dimensional teaching model whose shadow-zone angles differ from the real Earth."},"formula":"d ≈ (S−P) / (1/vₛ − 1/vₚ),  p = r sinθ / v","source":"../earth/geo/seismic-waves/#step3","lessons":[{"slug":"seismic-waves","step":3,"category":"earth","stage":"senior","primary":true}]},
"standing-wave":{"description":{"zh":"两列相同的波迎面相遇叠加，波形不再前进、只在原地起伏：有的点始终不动（波节），有的点振幅最大（波腹）；两端固定的弦只允许 L = nλ/2 的波长，驱动频率对上其中之一就会共振。","en":"Two identical waves meeting head-on add into a pattern that no longer travels and only rises and falls in place: some points never move (nodes) and others swing hardest (antinodes); a string fixed at both ends allows only wavelengths with L = nλ/2, and driving it at one of those frequencies makes it resonate."},"formula":"y = 2A cos(kx) sin(ωt), L = nλ/2","source":"../physics/waves/standing-wave/#step1","lessons":[{"slug":"standing-wave","step":1,"category":"physics","stage":"senior","primary":true}],"aliases":{"zh":["驻波","波节 波腹","弦的谐波","基频","为什么吉他弦只发出某些音","简正模式","驻定波","吉他弦怎么发出不同的音","弦振动","琴弦"],"en":["standing wave","nodes and antinodes","harmonics of a string","fundamental frequency","why does a guitar string sound only certain notes","normal mode","stationary wave","string vibration","guitar string","how guitar strings make notes"]}},
"work-energy":{"description":{"zh":"质点沿实际位移所受的净功等于动能变化。本理想水平弹簧中，弹簧力是唯一做非零功的力，故 Wspring=ΔK=−ΔU。","en":"Net work along a particle’s displacement equals its kinetic-energy change. In this ideal horizontal spring, only the spring does nonzero work, so Wspring=ΔK=−ΔU."},"formula":"Wnet = ∫ Fnet dx = ΔK","source":"https://openstax.org/books/university-physics-volume-1/pages/7-3-work-energy-theorem","help":{"title":{"zh":"本模型中的能量与单位","en":"Energy and units in this model"},"body":{"zh":"K=½mv² 是动能，U=½kx² 是弹簧弹性势能（平衡处取 U=0），E=K+U。1J=1N·m。本实验限于无阻尼、无持续驱动的理想水平弹簧；回复力仍存在。","en":"K=½mv² is kinetic energy; U=½kx² is elastic spring energy, with U=0 at equilibrium; E=K+U. One joule is1N·m. This experiment is an ideal horizontal spring with no damping or sustained driving; restoring force remains."},"sources":[{"href":"https://openstax.org/books/university-physics-volume-1/pages/8-1-potential-energy-of-a-system","label":{"zh":"OpenStax · 弹簧势能 ↗","en":"OpenStax · elastic energy ↗"}}]}},
"double-slit":{"description":{"zh":"双缝条纹间距 Δy = λL/d，被单缝 sinc² 包络罩住；一颗颗粒子的落点累积成条纹，知道走了哪条缝则条纹消失（V² + D² ≤ 1）；物质波长 λ = h/(mv)。理想相干远场模型，不对“测量”做解释。","en":"Double-slit fringes are spaced Δy = λL/d under a single-slit sinc² envelope; single particles build the fringes dot by dot, and knowing which slit was used erases them (V² + D² ≤ 1); matter waves have λ = h/(mv). An ideal coherent far-field model that offers no interpretation of measurement."},"formula":"Δy = λL/d","source":"../physics/modern/double-slit/#step2","lessons":[{"slug":"double-slit","step":2,"category":"physics","stage":"university","primary":true}],"note":"Edges use existing atlas nodes interference and superposition.","aliases":{"zh":["波粒二象性","光是波还是粒子","衍射","单缝衍射"],"en":["wave particle duality","is light a wave or a particle","diffraction"]}},
"fourier":{"description":{"zh":"用不同频率的正弦或复指数分量描述信号。周期信号用级数，有限采样数据可用离散傅里叶变换。","en":"Describe a signal using sinusoidal or complex-exponential components. Periodic signals use a series; finite sampled data can use a discrete Fourier transform."},"formula":"time ↔ frequency","source":"../signal/transforms/fourier/#step5","lessons":[{"slug":"fourier","step":5,"category":"signal","stage":"university","primary":true}]},
"gravitational-lensing":{"description":{"zh":"质量使光偏折 α = 4GM/(c²b)；点质量透镜方程 β = θ − 1/θ 给出两个像，光源在连线上时成爱因斯坦环；θE 随质量平方根增大，恒星是毫角秒（微引力透镜），星系是角秒（弧与环）；可由环的大小称出透镜质量。点质量、弱场、薄透镜模型。","en":"Mass deflects light by α = 4GM/(c²b); the point-mass lens equation β = θ − 1/θ gives two images, and a source on the axis forms an Einstein ring; θE grows with the square root of the mass, milliarcseconds for stars (microlensing) and arcseconds for galaxies (arcs and rings); the ring size weighs the lens. A point-mass, weak-field, thin-lens model."},"formula":"θE = √(4GM/c² · D_ls/(D_l D_s))","source":"../earth/astronomy/gravitational-lensing/#step2","lessons":[{"slug":"gravitational-lensing","step":2,"category":"earth","stage":"university","primary":true}],"note":"Edges use atlas nodes snell and work-energy only where real; gravitational-lensing is a new concept id."},
"kinetic-theory":{"description":{"zh":"二维硬圆盘气体：压强是大量分子撞墙的冲量平均，温度是平均动能——把气球放进热水，分子撞得更猛更快，气球就胀大；分子互相碰撞、不断交换能量，自然生成麦克斯韦速率分布，不用事先设定。不是三维真实气体。","en":"A 2D hard-disc gas: pressure is the average impulse of many molecules hitting the walls, temperature is mean kinetic energy — warm a balloon and its molecules hit harder and faster, so it swells. Collisions keep swapping energy and naturally generate the Maxwell speed distribution, nothing preset. Not a real 3D gas."},"formula":"P = N⟨KE⟩/A (2D), ⟨KE⟩ = kT","source":"../physics/thermal/kinetic-theory/#step0","lessons":[{"slug":"kinetic-theory","step":0,"category":"physics","stage":"university","primary":true}],"note":"group waves is the closest by atlas labels (motion & waves); the page is thermal physics","aliases":{"zh":["理想气体定律","理想气体","麦克斯韦分布","玻尔兹曼分布"],"en":["ideal gas law","ideal gas","maxwell-boltzmann distribution","boltzmann distribution"]}},
"modulation":{"description":{"zh":"把低频的声音乘上一个高频载波，整段频谱就搬到载波两侧，既能用尺寸合适的天线发得远，又能让许多电台各占一段频率；调幅（AM）改变载波的幅度，调频（FM）改变它的瞬时频率，接收端再把频谱搬回来。","en":"Multiplying a low-frequency signal by a high-frequency carrier moves its whole spectrum up beside the carrier, so it can travel far from a reasonably sized antenna and many stations can share the air on separate bands; AM varies the carrier’s amplitude, FM its instantaneous frequency, and the receiver moves the spectrum back down."},"formula":"s(t) = (1 + m·x(t))·cos(2πf_c t)","source":"../signal/sampling/modulation/#step1","lessons":[{"slug":"modulation","step":1,"category":"signal","stage":"university","primary":true}],"aliases":{"zh":["调幅 调频","AM 和 FM 的区别","载波","边带","解调","收音机怎么选台","频分复用","IQ 调制"],"en":["AM and FM","difference between AM and FM","carrier wave","sidebands","demodulation","how does a radio tune in one station","frequency-division multiplexing","I/Q modulation"]}},
"photoelectric-effect":{"description":{"zh":"关键反直觉处：打不打出电子不看光有多亮，而看单个光子的能量 hν——频率低于截止频率时，单个光子能量跨不过逸出功，再亮也打不出；频率够高时，哪怕光很暗也有电子飞出；遏止电压测出的就是这些电子的最大动能，从而测出 h。理想化模型，逸出功取教材近似值。","en":"The counterintuitive point: freeing an electron does not depend on how bright the light is, but on a single photon's energy hν — below the threshold frequency, one photon cannot clear the work function, so no brightness helps; above it, even dim light frees electrons, and the stopping voltage measures those electrons' maximum kinetic energy, giving h. An idealised model with rounded textbook work functions."},"formula":"E_k,max = hf − φ","source":"../physics/modern/photoelectric-effect/#step1","lessons":[{"slug":"photoelectric-effect","step":1,"category":"physics","stage":"university","primary":true}]},
"quantum-amplitude":{"description":{"zh":"一个量子比特可以同时保留 |0⟩ 和 |1⟩ 两种可能、各带一个振幅；测量时按振幅的平方随机给出一个结果，而带相位的振幅相加时既能增强也能抵消，这就是量子干涉。","en":"A qubit can hold both possibilities |0⟩ and |1⟩ at once, each with an amplitude; a measurement returns one outcome at random with probability equal to the amplitude squared, and amplitudes carrying phase can add up or cancel — quantum interference."},"formula":"P = |amplitude|²","source":"../physics/modern/quantum-basics/#step0","lessons":[{"slug":"quantum-basics","step":0,"category":"physics","stage":"university","primary":true}],"aliases":{"zh":["量子叠加","量子比特","薛定谔的猫","波函数坍缩","概率幅","玻恩规则","量子到底是什么意思","量子干涉","量子力学","量子力学是什么","叠加态","量子物理"],"en":["quantum superposition","qubit","Schrödinger’s cat","wavefunction collapse","probability amplitude","Born rule","what does quantum actually mean","quantum interference","quantum mechanics","what is quantum mechanics","quantum physics","schrodinger's cat"]}},
"quantum-tunneling":{"description":{"zh":"稳态波函数在矩形势垒内指数衰减、墙后留有透射份额；透射概率随墙宽指数下降、随能量出现共振；含时波包撞墙分成反射与透射；扫描隧道显微镜用隧穿电流的指数灵敏度；质量越大概率越小。一维、非相对论、单粒子模型。","en":"A steady wave function decays exponentially inside a rectangular barrier and leaves a transmitted share; transmission falls exponentially with width and shows resonances with energy; a wave packet splits at the wall; the scanning tunnelling microscope exploits the exponential sensitivity; heavier particles tunnel far less. A one-dimensional, non-relativistic, single-particle model."},"formula":"T ≈ e^{−2κa}, κ = √(2m(V₀−E))/ħ","source":"../physics/modern/quantum-tunneling/#step1","lessons":[{"slug":"quantum-tunneling","step":1,"category":"physics","stage":"university","primary":true}],"note":"quantum-basics is a page slug, not an atlas node; edges use atlas nodes interference and sampling.","aliases":{"zh":[],"en":["quantum tunneling","tunneling","tunnelling"]}},
"relativity":{"description":{"zh":"从光速不变出发：光钟的时间膨胀、时空图与洛伦兹变换、同时性的相对性、缪子寿命的实证、相对论速度合成，以及动能发散说明有质量的粒子到不了光速。惯性观察者、一维、c = 1 的模型。","en":"Starting from a constant speed of light: time dilation in a light clock, spacetime diagrams and the Lorentz transformation, the relativity of simultaneity, muon lifetimes as evidence, relativistic velocity addition, and diverging kinetic energy showing why massive particles cannot reach c. Inertial observers, one dimension, c = 1."},"formula":"γ = 1/√(1 − β²),  u = (v + w)/(1 + vw)","source":"../physics/modern/relativity/#step1","lessons":[{"slug":"relativity","step":1,"category":"physics","stage":"university","primary":true}],"note":"Physics advanced page; group follows atlas mechanics/wave nodes."},
"resonance":{"description":{"zh":"像推秋千踩中节拍：受周期驱动的系统，响应幅度可能在某个频率附近出现峰值——外推频率等于固有频率时振幅最大；阻尼越小峰越尖越高，阻尼越大峰越矮越宽，偏一点频率也推得起来一些。","en":"Like pushing a swing in time: a periodically driven system may respond most strongly near a particular frequency — amplitude peaks when the driving frequency equals the natural frequency. Lighter damping makes the peak taller and sharper; heavier damping makes it lower and wider, so slightly off-frequency pushes still build a little."},"formula":"drive → response peak","source":"../physics/waves/resonance/#step3","lessons":[{"slug":"frequency-response","step":5,"category":"signal","stage":"university","primary":true},{"slug":"resonance","step":3,"category":"physics","stage":"senior","primary":false}]},
"sampling":{"description":{"zh":"按固定时间间隔记录信号。理想带限信号的采样率需高于最高频率的两倍，才能避免频谱重叠。","en":"Record a signal at fixed intervals. For an ideally band-limited signal, a sampling rate above twice its highest frequency avoids overlapping spectral copies."},"formula":"fₛ > 2fₘₐₓ","source":"../signal/sampling/sampling/#step3","lessons":[{"slug":"sampling","step":3,"category":"signal","stage":"university","primary":true}],"aliases":{"zh":["采样定理","奈奎斯特","混叠"],"en":["sampling theorem","nyquist","nyquist theorem","aliasing"]}},
"spectrum":{"description":{"zh":"按频率列出信号分量的幅度与相位——一段音乐、一串语音，频谱就是它的“成分表”：横轴频率、纵轴每种频率占多少。幅度图只展示其中一部分，不能单独还原一般信号：只看幅度丢了相位，就像只看菜谱的配料不看做法。","en":"List a signal's component amplitudes and phases by frequency — for a piece of music or a stretch of speech, the spectrum is its 'ingredient list': frequency across, each frequency's share up. A magnitude plot alone shows only part of it and cannot reconstruct a general signal: magnitude without phase is like a recipe's ingredients without the method."},"formula":"X(f)","source":"../signal/transforms/fourier/#step5","lessons":[{"slug":"fourier","step":5,"category":"signal","stage":"university","primary":true}]},
"stress-strain":{"description":{"zh":"把材料拉长时，应力（单位面积上的力）对应变（相对伸长）的曲线先是一段直线（弹性，松手能回去），过了屈服点开始永久变形，最后颈缩断裂；曲线下的面积是断裂前吸收的能量，叫韧性。","en":"As a material is stretched, its curve of stress (force per area) against strain (relative stretch) starts as a straight line (elastic — it springs back), turns into permanent deformation past the yield point, and ends in necking and fracture; the area under the curve is the energy absorbed before breaking, called toughness."},"formula":"σ = F/A, ε = ΔL/L₀, σ = Eε","source":"../physics/matter/materials-science/#step1","lessons":[{"slug":"materials-science","step":1,"category":"physics","stage":"university","primary":true}],"aliases":{"zh":["应力 应变","杨氏模量","屈服强度","韧性","塑性变形","脆性与延性","为什么玻璃会碎而钢会弯","胡克定律"],"en":["stress and strain","Young’s modulus","yield strength","toughness","plastic deformation","brittle vs ductile","why does glass shatter while steel bends","Hooke’s law"]}},
"superposition":{"description":{"zh":"把多个信号在同一时刻的值相加，得到合成信号：两列水波相遇、各走各的路，交汇处的高度就是两者相加。物理系统是否允许这样叠加取决于其线性——线性系统里，复杂输入可以拆成简单输入分别算、再叠起来；非线性系统这招不灵。","en":"Add several signals' values at the same instant to form a combined signal: two water waves meet and pass through each other, and the height where they cross is their sum. Whether a physical system allows such superposition depends on its linearity — in a linear system a complex input can be split into simple inputs, solved separately and added back; in a nonlinear system that trick fails."},"formula":"y(t) = x₁(t) + x₂(t)","source":"../signal/transforms/fourier/#step2","lessons":[{"slug":"fourier","step":2,"category":"signal","stage":"university","primary":true}]},
"wavelets":{"description":{"zh":"傅里叶幅度谱说明有哪些频率却不含先后；加窗与小波让分析同时定位时间与频率。离散教学模型：高斯窗与 Morlet 小波，边界补零。","en":"A Fourier magnitude spectrum shows which frequencies are present but not their order; windows and wavelets locate frequency in time. Discrete teaching model: Gaussian window and Morlet wavelet with zero padding."},"formula":"σt·σf = 1/(2π)  (Gaussian window)","source":"../signal/transforms/wavelets/#step2","lessons":[{"slug":"wavelets","step":2,"category":"signal","stage":"university","primary":true}]}
}});
